#include <bits/stdc++.h>

#define ll long long

using namespace std;

void solve(){
    ll n;cin>>n;
    ll N = 3*n;
    vector<ll> a(N);
    for(auto &pos:a)cin>>pos;
    
    sort(a.begin(),a.end());
    
    // vector<vector<ll>> dp(N+1,vector<ll>(N+1,0));
    
    // for(ll i=N-1;i>=0;i--){
    //     for(ll j=i+2;j<N;j+=3){
    //         dp[i][j] = max({6 * a[j] + dp[i+2][j-1], 4*(a[j]+a[j-1]) +dp[i+1][j-2], 3 * (a[j] + a[j-1] + a[j-2]) + (j>=3?dp[i][j-3]:0)});
    //     }
    // }
    
    // cout<<dp[0][N-1]<<endl;
    
    
    vector<ll> pref(N+1,0);
    for(ll i=0;i<N;i++){
        pref[i+1] = pref[i] + a[i];
    }
    ll ans = -1e18;
    for(ll i=0;i<=n;i++){
        ll idx = 0;
        ll low = 0-1, high = n - i;
        
        auto f = [&](ll mid)->ll{
          ll val = (pref[N - i] - pref[N-i - 2*mid]) * 4;
        //   cout<<"in f"<<val<<endl;
          val += (pref[N-i-2*mid] - pref[2 * i + mid])*3;
          return val;
        };
        
        while(high - low>1){
            ll mid = (low+high)>>1;
            if(f(mid)>f(mid+1)){
                high = mid;
            }else low = mid;
        }
        
        idx = low + 1;
        // cout<<idx<<endl;
        ll cur = f(idx);
        // cout<<cur<<" "<<i<<endl;
        cur += (6 * (pref[N] - pref[N-i]));
        
        ans = max(ans, cur);
        
        
    }
    
    cout<<ans<<"\n";
}

int main() {
	// your code goe4s here
	ll tt;cin>>tt;
	while(tt--)solve();
}
